const { useState, useEffect } = React;

const COURSES = [
  { id: 1, name: '리액트 입문', hours: 8 },
  { id: 2, name: 'CSS 레이아웃', hours: 6 },
  { id: 3, name: '자바스크립트 기초', hours: 12 },
];

function readRoute() {
  return window.location.hash.slice(1) || '/';
}

function App() {
  const [route, setRoute] = useState(readRoute());

  useEffect(() => {
    const onChange = () => setRoute(readRoute());
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);

  return (
    <div>
      <nav className="nav">
        <a href="#/">홈</a>
        <a href="#/courses">코스</a>
      </nav>
      {route === '/courses' ? (
        <div>
          <p className="state">코스 {COURSES.length}개</p>
          {COURSES.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
        </div>
      ) : (
        <p className="state">홈 화면입니다</p>
      )}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

